-- frFR texts carrying HTML entities (&lt;, &nbsp;, <br>) decoded in the French texts of existing quests; wording
-- unchanged; rows still in English are left as they are. Broken markup of the existing text also fixed in 8584, 10918,
-- 10973, 11007 and 25417 ($G instead of <, B$B$B, missing >).
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le maître de guerre Laggrond rugit.>$B$BIls commencent à raconter vos exploits, soldats. Les Foudrepiques tremblent de peur lorsqu’ils entendent votre nom. Continuez !' WHERE `ID` = 7165 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le grand maréchal Afrasiabi s’incline.>$B$BChoisissez votre récompense, et que les réjouissances commencent !' WHERE `ID` = 7782 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Dirge se gratte la tête.>$B$BUn poulet de 500 livres ? Ça n’existe pas. Enfin, plus. J’ai entendu parler d’un tel poulet… le poulet noir de la mort…$B$B<Dirge baisse la voix, puis reprend.>$B$BMais bon, personne n’a jamais vu ce poulet. Personne de vivant, en tout cas. Mais j’ai une autre idée qui pourrait nous être profitable à tous les deux, mon gars.' WHERE `ID` = 8584 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Narain plonge les deux mains dans le poulet géant et commence à se goinfrer du délicieux plat de Dirge.>$B$BMmmmmm…. C’est incroyable ! Jamais mangé de meilleur poulet !' WHERE `ID` = 8587 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Narain devient écarlate.>$B$BAlors comme ça, ils ont fauché mon livre, hein ? Je vais leur apprendre qu’on ne marche pas sur les pieds d’un gnome doté de pouvoirs psychiques !' WHERE `ID` = 8598 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Incroyable ! Il faudrait des centaines de sporelins pour tuer autant de géants que vous. Je ferai en sorte que chacun connaisse vos exploits !$B$B<Cette quête est répétable jusqu''au niveau de réputation Amical.>' WHERE `ID` = 9744 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Excellent. Continuez à m''apporter des morceaux de plantes si vous en trouvez d''autres.$B$B<Cette quête peut être répétée jusqu''à ce que vous soyez Honoré.>' WHERE `ID` = 9784 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Une nouvelle espèce ! En êtes-vous sûr ?$B$B<Lauranna parcourt ses pages de notes et de diagrammes.>$B$BBon travail, $N. Nous allons l''ajouter à notre liste. « Winstubrium à feuilles violettes », ça vous va ? Je trouve que ça sonne bien.' WHERE `ID` = 9875 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Les yeux de l''archimage s''éclairent lorsque vous lui donnez la pierre.>$B$BFabuleux ! Si je me fie au peu que j''ai vu du destin de Farahlon, je ne suis pas sûr de vouloir sortir, mais cela vaut toujours beaucoup mieux que de rester enfermé ici jusqu''à la fin de mes jours.' WHERE `ID` = 10257 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Oui... Les troupes de Kael continuent de décroître alors que nous nous faisons plus nombreux.$B$B<Cette quête est répétable jusqu''au niveau de réputation Honoré.>' WHERE `ID` = 10414 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Ordinn prend le fragment d''arme que vous lui tendez.>$B$BCela faisait longtemps que je n''avais pas vu une chose pareille. De toute évidence, il s''agit d''un minerai rare, mais ce fragment n''est pas destiné à une arme quelconque, $N. Il est imprégné d''une magie destinée à détruire les démons. Si vous vous êtes procuré ceci sur un membre de la Légion, il doit s''agir d''une sorte d''"arme secrète" qu''ils prévoient d''utiliser contre Illidan. Quelle trouvaille !' WHERE `ID` = 10621 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<David feuillette le livre et frémit.>$B$BC''est loin d''être quelque chose à prendre à la légère, $N. Une fois que l''arme sera créée, je le détruirai. Il y a déjà assez de puissance démoniaque sans que ce texte soit dans la nature.' WHERE `ID` = 10666 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Eh bien, eh bien, eh bien… Mais c’est le grunt que j’ai envoyé au combat. Vous êtes revenu, et en un seul morceau, par-dessus le marché.$B$B<Or''barokh hoche la tête.>$B$BJe savais que vous ne me décevriez pas, soldat. Vous avez stoppé une avance illidari importante, et vous méritez bien une petite récompense.' WHERE `ID` = 10769 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Eh bien, eh bien, eh bien… Mais c’est le soldat que j’ai envoyé au combat. Vous êtes revenu, et en un seul morceau, par-dessus le marché.$B$B<Yoregar hoche la tête.>$B$BJe savais que vous ne me décevriez pas, soldat. Vous avez stoppé une avance illidari importante, et vous méritez bien une petite récompense.' WHERE `ID` = 10776 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Vekax caquette de joie alors que vous lui présentez la preuve de la défaite de ses ennemis.>$B$BTrès bien, cela montrera à Skettis que nous autres les parias ne nous laisserons pas punir sans réagir. Voici la récompense que je vous ai promise. Je peux me débrouiller pour vous donner un supplément, si vous me rapportez d’autres plumes.$B<Cette quête peut être répétée jusqu’au niveau de réputation Honoré.>' WHERE `ID` = 10918 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Fei Fei aboie joyeusement et attrape la friandise pour chien. Il regarde à droite et à gauche... et semble décider de l’endroit où il va cacher son nouveau trésor...>' WHERE `ID` = 10919 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Ameer combine habilement les clés, et commence à lire les inscriptions sur la nouvelle tablette-clé.>$B$B« Un millier de mondes brisés, un autre millier de mondes à soumettre… Telle est la volonté du roi-nexus. »$B<Ameer retourne la tablette et commence à lire le dos des plaques.>$B$BLes chambres de stase de Bash’ir ?' WHERE `ID` = 10973 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<L''image du commandant Ameer inspecte les indices.>$B$BC''est pire que je ne croyais… Ces chambres renferment des bêtes féroces et des créatures venues de très nombreux mondes. Ils espèrent parvenir un jour à leur imposer leur volonté. Il faut toutes les détruire !' WHERE `ID` = 10974 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Enfin !$B$B<Le commandant Ameer lit ce qui est inscrit sur la Marque du roi-nexus.>$B$BDeux dernières prisons ? J''ai des sueurs froides à l''idée des horreurs qui nous y attendent…' WHERE `ID` = 10976 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Les pensées d''A''dal se mêlent aux vôtres.>$B$BLa sphère... Étrange. Saviez-vous qu''il était vivant ? Oui. Ici - dans la sphère. Estropié, sans aucun doute. Il fait appel à un pouvoir plus grand à présent. Non, pas Illidan.$B$BPlus puissant que lui.$B$BKil''jaeden le Trompeur arrive...$B$BPas ici...$B$B<A''dal indique un autre endroit à votre esprit.>$B$BAzeroth. Sans qu''on le sache.$B$BReposez-vous. Vos frères et sœurs vont reprendre le donjon de la Tempête maintenant.$B$B<A''dal fait résonner un chant de bataille.>' WHERE `ID` = 11007 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le chef inspecte le contenu de la caisse.>$B$BTout a l''air parfait. Encore une chose que je peux cocher sur ma liste. Maintenant, il ne reste plus qu''à faire décoller la fusée !' WHERE `ID` = 11036 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Chu''a''lor vous adresse un sourire radieux, empreint d’un grand respect.>$B$BNon seulement nous sommes très impressionnés par votre agilité mentale et celle de vos amis, mais nous avons une dette envers vous, comme tout Ogri’la et la Garde-ciel, pour avoir protégé notre mode de vie.$B$BEt n’oubliez pas, $N, vous pouvez quand vous le voulez rassembler d’autres personnes et retourner dans ces monuments apogides pour les utiliser. Il vous suffit d’avoir les éclats apogides nécessaires pour les alimenter.' WHERE `ID` = 11059 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Bon, bon, on dirait que vous aviez l''étoffe pour, après tout. Bon travail. P''têt'' que le vieux Keller se trompait sur votre compte.$B$B<Le sergent Vanderlip de la Garde-ciel sourit d''un air narquois.>' WHERE `ID` = 11102 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Donna surveille les environs avant de se mettre à chuchoter à votre oreille.>$B$B$N, ce que je vais vous confier doit rester confidentiel, c’est compris ?$B$BJ’ai été envoyée ici par les gardes-paix de Shattrath pour infiltrer le gang de Budd. Je dois avouer que depuis votre arrivée vous avez tenu un rôle clé dans mon enquête.$B$BMais vos actes vous ont lavé de tout soupçon. Et même, pour avoir tué ce cinglé de chef de guerre, Zul’jin, je me dois de vous récompenser.' WHERE `ID` = 11163 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Vous sentez un profond sentiment de satisfaction émaner du marchand des vents.>$B$BBien, je suis très heureux d’apprendre sa fin. Et peut-être que je parviendrai à m’approprier les secrets de son amulette. Sinon, je la revendrai pour un bon prix.$B$BJ’espère que cette récompense vous suffit.$B$BRevenez demain et j’aurai autre chose à vous proposer.' WHERE `ID` = 11373 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Vous sentez l''approbation de Zim''Abwa. Vous ne savez dire comment, mais vous devinez que Zim''Abwa veut plus de marques de déférence !>' WHERE `ID` = 12567 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<La Mère de la prospérité vous transmet son approbation.>' WHERE `ID` = 12618 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Zim''Rhuk impose une image dans votre esprit d''un de ses gardiens vous écrasant sous sa botte. Vous devriez peut-être essayer d''apaiser Zim''Rhuk avec plus d''offrandes.>' WHERE `ID` = 12656 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Quelle corvée de faire en sorte que les tables restent bien garnies. Quand on y pense, c''est étrange de se donner tellement de mal alors que nous n''avons plus besoin de manger.$B$B<William hausse les épaules.>$B$BLa tradition, c''est la tradition.' WHERE `ID` = 14037 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Caladis vous prend la poignée et la retourne lentement entre ses mains.>$B$BCette poignée m''est vaguement familière, comme si j''étais censé en connaître l''origine. Vous dites que vous l''avez récupérée dans la citadelle ? Très intrigant.$B$BLes gens capables de forger une telle lame sont très peu nombreux. Peut-être pourront-ils nous dire quelque chose à propos de votre découverte.' WHERE `ID` = 14443 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<L’arcaniste Tybalin examine les ordres capturés.>$B$BL’agent que vous avez intercepté était supposé transporter le Livre du Repos du ver à la Couronne de glace après avoir rencontré un certain magistère Hathorel, au sanctuaire de Saccage-soleil. Nous devons nous procurer cet ouvrage, $N, et c’est une chance qu’il faut saisir. Mais cela ne va pas être facile…' WHERE `ID` = 14457 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Caladis accepte le lourd ouvrage et commence à le feuilleter.>$B$BJe savais bien que les symboles gravés sur la lame m’étaient familiers. Cette arme a sûrement été forgée par les dragons, et offerte à un mortel. Mais à qui cette lame appartenait-elle, et comment se fait-il qu’elle repose dans la Couronne de glace ?' WHERE `ID` = 24454 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Jaina est encore en train de reprendre son souffle.>$B$BJ''ai peine à croire que nous soyons encore en vie. J''ai été folle de le suivre. J''ai fait cette erreur de trop nombreuses fois. Et vous... il était imprudent de votre part de venir me chercher au lieu de fuir avec l''information ! Mais... eh bien... merci. Vous êtes un véritable héros.$B$BAvec les conseils d''Uther, nous avons peut-être une chance de vaincre Arthas. Les morts d''aujourd''hui n''auront pas été vaines.' WHERE `ID` = 24500 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Hé, merci, petit. Donnez-moi ça, que j''y jette un œil.$B$B<Il vous prend l''appareil et le tripote.>$B$BOh, c''est pas bon.' WHERE `ID` = 24536 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Vous l''avez, hein ? Beau travail, gamin. Joli. Voyons voir ce qu''on a.$B$B<Il ouvre la caisse et fouille à l''intérieur.>' WHERE `ID` = 24541 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le généralissime Mograine vous regarde en silence pendant un moment.>$B$BVous semblez avoir supporté admirablement cette partie de votre épreuve, $R.$B$BPriez que le destin continue à vous sourire dans vos efforts...' WHERE `ID` = 24547 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Hé, merci, petit. Donnez-moi ça, que j''y jette un œil.$B$B<Il vous prend l''appareil et le tripote.>$B$BOh, c''est pas bon.' WHERE `ID` = 24655 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Vous l''avez, hein ? Beau travail, gamin. Joli. Voyons voir ce qu''on a.$B$B<Il ouvre la caisse et fouille à l''intérieur.>' WHERE `ID` = 24656 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Vous... Vous n''êtes pas Chignard. Est-ce qu''il vous envoie ? Il est tellement en retard que je commençais à perdre espoir...$B$B<Les larmes gonflent dans les yeux de la femme quand elle réalise que vous n''êtes pas là pour lui donner un message de Chignard.>$B$BCe n''est pas le genre de mon Chignard, mais quel autre choix y a-t-il ?' WHERE `ID` = 24848 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Vous n’êtes pas Chignard. Il était censé revenir il y a une heure! Qu’avez-vous fait de lui ?$B$B<Roka se calme un peu lorsque vous lui expliquez que vous cherchez Chignard, avant de se mettre à pleurer.>$B$BÇa ne ressemble pas à mon doux Chignard. Il a dû lui arriver quelque chose, vous ne croyez pas ?' WHERE `ID` = 24850 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Après avoir tracé un motif complexe de runes sur chaque surface de la boîte, le contour d''un couvercle apparaît et un clic retentit dans la chambre.>$B$BVous voilà, $R.' WHERE `ID` = 24914 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Torek parcourt les pamphlets que vous avez collectés.>$B$BQui que soient ces personnes, elles cherchent vraiment des partisans. Et on dirait bien qu''elles rencontrent un certain succès. Nous ne pouvons pas les laisser propager la panique et la paranoïa parmi les habitants d''Orgrimmar. Nous devons faire en sorte que ce groupe perde de son intérêt pour la population et en apprendre le plus possible sur lui.' WHERE `ID` = 25228 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Anton parcourt les parchemins que vous avez collectés.>$B$BCeux qui ont rédigé ces pamphlets savent s''y prendre pour attirer l''attention et d''après ce qu''il se passe dans la vieille ville, les habitants semblent très intéressés. Nous devons agir avant que leurs partisans ne deviennent trop nombreux. Je crains qu''ils n''usent de leur influence pour répandre la panique dans tout Hurlevent et nous paralyser.$B$BNous devons nous infiltrer dans leur organisation et en apprendre le plus possible.' WHERE `ID` = 25253 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Alors, vous les avez trouvés ? Pourquoi les disparus ne sont-ils pas revenus avec vous ?$B$B<Vous racontez au garde de sang les réponses qu''ils vous ont faites.>$B$BNous ne pouvons pas les forcer à changer d''avis et à retourner auprès des leurs. Je ferai savoir aux familles que leurs proches ont été retrouvés et sont sains et saufs. Lorsque le Culte aura été détruit, ces personnes reprendront probablement leur vie d''avant.' WHERE `ID` = 25293 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Vous tendez au garde de sang Torek les appareils que la surveillante vous a confiés et vous lui expliquez les projets du culte. Les yeux de Torek s''écarquillent.>$B$BCho''Gall est à la tête du culte ? Alors il ne peut s''agir que du Marteau du crépuscule ! Vous n''êtes probablement pas le seul qu''ils ont envoyé en ville installer ces appareils.' WHERE `ID` = 25347 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le chef de guerre écoute votre rapport d''enquête sur le complot du Marteau du crépuscule pour détruire Orgrimmar.>$B$BVous êtes un membre dévoué de la Horde, $N, et vous avez bien fait de m’avertir de ceci. Je veillerai personnellement à ce que nos ennemis aient ce qu’ils méritent !' WHERE `ID` = 25351 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Alors, vous les avez trouvés ? Pourquoi les disparus ne sont-ils pas revenus avec vous ?$B$B<Vous dites au capitaine qu''ils avaient l''air déterminés à rester pour diverses raisons.>$B$BDans ce cas, nous ne pouvons pas les forcer à rentrer. Tout ce que je peux espérer, c''est que les sectateurs réaliseront à temps le mal qu''ils ont fait et décideront de reprendre leur ancienne vie.$B$BMerci pour vos efforts, $N. J''irai annoncer aux familles ce que vous avez découvert.' WHERE `ID` = 25414 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Vous tendez au capitaine Anton les appareils élémentaires que la surveillante vous a confiés et vous lui expliquez les projets du culte.>$B$BCho''Gall est à la tête du culte ? Alors il ne peut s''agir que du Marteau du crépuscule ! Nous les suspections de vouloir frapper de nouveau, mais personne ne savait de quelle façon.$B$BVous avez fait un excellent travail pour découvrir ce complot. Malheureusement, vous n''êtes probablement pas le seul qu''ils ont envoyé en ville installer ces appareils.' WHERE `ID` = 25417 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Le visage du roi exprime tout d''abord l''inquiétude, puis la colère, lorsque vous lui expliquez le complot ourdi par le Marteau du crépuscule pour détruire Hurlevent.>$B$BComment osent-ils frapper Hurlevent ? Comment osent-ils tenter de manipuler les habitants de cette cité pour les retourner contre nous et contre l''Alliance ? Sans votre courage aujourd''hui, $N, notre ville n''aurait pas découvert les projets du Marteau du crépuscule. Vous êtes un véritable héros pour Hurlevent et pour l''Alliance.' WHERE `ID` = 25425 AND `locale` = 'frFR';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<Krasus vous écoute attentivement alors que vous lui racontez votre combat contre Halion, et ses yeux s’écarquillent de stupeur quand vous mentionnez le nom d’Aile de mort.>$B$BNous avons une grande dette envers vous, mortel, pour avoir repoussé les envahisseurs du sanctum, et nous vous serons éternellement reconnaissants. Mais cette histoire du Destructeur me trouble profondément. Il va falloir que j’en discute avec les autres membres de l’Accord.$B$BRecevez ceci en témoignage de ma gratitude, cela vous aidera à vous préparer pour l’orage qui gronde.' WHERE `ID` = 26034 AND `locale` = 'frFR';
